-- 2026년 11월 User/Settlement 배치 검증용 MySQL 더미데이터

-- 생성 명령: python3 scripts/generate_phase1_dummy_data.py

SET NAMES utf8mb4;
SET time_zone = '+09:00';

CREATE TABLE IF NOT EXISTS `shop_user` (
    `user_id` BIGINT NOT NULL,
    `login_id` VARCHAR(50) NOT NULL,
    `password_hash` VARCHAR(255) NOT NULL,
    `name` VARCHAR(100) NOT NULL,
    `point_balance` BIGINT NOT NULL DEFAULT 0,
    `account_status` VARCHAR(20) NOT NULL,
    `last_login_at` DATETIME NOT NULL,
    `dormant_at` DATETIME NULL,
    PRIMARY KEY (`user_id`),
    UNIQUE KEY `uk_shop_user_login_id` (`login_id`),
    KEY `idx_shop_user_dormancy` (`account_status`, `last_login_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `shop_order` (
    `order_id` BIGINT NOT NULL,
    `user_id` BIGINT NOT NULL,
    `orderer_name` VARCHAR(100) NOT NULL,
    `ordered_at` DATETIME NOT NULL,
    `order_status` VARCHAR(20) NOT NULL,
    `order_amount` BIGINT NOT NULL,
    `refund_amount` BIGINT NOT NULL DEFAULT 0,
    `net_amount` BIGINT NOT NULL,
    PRIMARY KEY (`order_id`),
    KEY `idx_shop_order_settlement` (`ordered_at`, `order_status`),
    CONSTRAINT `fk_shop_order_user`
        FOREIGN KEY (`user_id`) REFERENCES `shop_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `order_item` (
    `order_item_id` BIGINT NOT NULL,
    `order_id` BIGINT NOT NULL,
    `product_id` BIGINT NOT NULL,
    `product_name` VARCHAR(255) NOT NULL,
    `quantity` BIGINT NOT NULL,
    `unit_price` BIGINT NOT NULL,
    `line_total` BIGINT NOT NULL,
    PRIMARY KEY (`order_item_id`),
    KEY `idx_order_item_order_id` (`order_id`),
    CONSTRAINT `fk_order_item_order`
        FOREIGN KEY (`order_id`) REFERENCES `shop_order` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `point_lot` (
    `point_id` BIGINT NOT NULL,
    `user_id` BIGINT NOT NULL,
    `earned_at` DATETIME NOT NULL,
    `expires_at` DATETIME NOT NULL,
    `original_amount` BIGINT NOT NULL,
    `remaining_amount` BIGINT NOT NULL,
    `status` VARCHAR(20) NOT NULL,
    PRIMARY KEY (`point_id`),
    KEY `idx_point_lot_expiration` (`status`, `expires_at`),
    CONSTRAINT `fk_point_lot_user`
        FOREIGN KEY (`user_id`) REFERENCES `shop_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `expected_dormant_transition` (
    `transition_date` DATE NOT NULL,
    `user_id` BIGINT NOT NULL,
    `previous_status` VARCHAR(20) NOT NULL,
    `next_status` VARCHAR(20) NOT NULL,
    `last_login_at` DATETIME NOT NULL,
    `dormant_at` DATETIME NOT NULL,
    PRIMARY KEY (`transition_date`, `user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `daily_settlement` (
    `settlement_date` DATE NOT NULL,
    `daily_order_count` BIGINT NOT NULL,
    `settled_order_count` BIGINT NOT NULL,
    `total_product_quantity` BIGINT NOT NULL,
    `gross_sales_amount` BIGINT NOT NULL,
    `refund_amount` BIGINT NOT NULL,
    `net_sales_amount` BIGINT NOT NULL,
    `calculated_at` DATETIME NOT NULL,
    PRIMARY KEY (`settlement_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `daily_product_settlement` (
    `settlement_date` DATE NOT NULL,
    `product_id` BIGINT NOT NULL,
    `product_name` VARCHAR(255) NOT NULL,
    `quantity` BIGINT NOT NULL,
    `unit_price` BIGINT NOT NULL,
    `sales_amount` BIGINT NOT NULL,
    PRIMARY KEY (`settlement_date`, `product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `daily_point_expiration` (
    `expiration_date` DATE NOT NULL,
    `source_row_count` BIGINT NOT NULL,
    `target_count` BIGINT NOT NULL,
    `expired_point_amount` BIGINT NOT NULL,
    `processed_at` DATETIME NOT NULL,
    PRIMARY KEY (`expiration_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

START TRANSACTION;

